# Lists every mention of the 7.5% IMT rate in the repo for the operator's legal check (prompt 30, 27 Oct).
# A line counts when it carries 7.5% (or 7,5 %) and IMT or a non-resident wording within four lines of it; in posts and
# newsletters every 7.5% counts. Price changes (+7.5%) and the IMI/AIMI rates for tax-haven owners are left out.
# Each mention is tagged: the flat rate for non-residents (art. 17.º, n.º 10, DL 97/2026), the top bracket for
# residents (above 1 150 853 €), or "check" when the line alone does not say which.
# Usage (repo root): python3 scripts/legal/imt_mentions.py > ops/legal/IMT_7_5_MENTIONS.md
import os, re, subprocess
RATE = re.compile(r"7[.,]5\s?%|7\.5 percent|7,5 por cento|\b0?\.075\b")
IMT = re.compile(r"IMT|transfer tax|imposto municipal sobre as transmiss|droits? de mutation|n[ãa]o[- ]resid|non[- ]?r[ée]sid|nonresid", re.I)
OTHER = re.compile(r"AIMI|IMI\b.*(offshore|favour|favor|regime)|r[ée]gime (fiscal )?(mais )?favor", re.I)
SKIP = ("site/public/data/", "content/facts/map/raw/", "node_modules/", "/dist/", ".astro/")
files = subprocess.run(["git", "ls-files"], capture_output=True, text=True).stdout.split("\n")
files += [f for f in subprocess.run(["git", "ls-files", "-o", "--exclude-standard"], capture_output=True, text=True).stdout.split("\n")]
GROUPS = [("Facts (the source of every figure)", "content/facts/"), ("Site code and calculators", "site/src/"), ("Site copy", "content/copy/"),
          ("FAQ answers", "content/faq/"), ("Blog and pillar pages", "content/blog/"), ("E-books (source; site/ebooks/out/ is generated from it)", "site/ebooks/"),
          ("Map area briefs", "content/map/"), ("Newsletters and pillars in the inbox", "content/inbox/"), ("Social posts", "social/"),
          ("Scripts that write posts", "scripts/"), ("Sponsor and ops documents", "sponsors/"), ("Sponsor and ops documents", "ops/"),
          ("Design notes", "design/"), ("Archived drafts (not in use; kept for reference)", "content/archive/")]
out = {}
for f in sorted(set(x for x in files if x and os.path.isfile(x))):
    if any(s in f for s in SKIP) or f.startswith("site/ebooks/out/") or f.endswith((".png", ".jpg", ".webp", ".pdf", ".mp4", ".woff2")) or f == "scripts/legal/imt_mentions.py" or f.startswith("ops/legal/"):
        continue
    try: L = open(f, encoding="utf8").read().split("\n")
    except (UnicodeDecodeError, OSError): continue
    for i, line in enumerate(L):
        if not RATE.search(line): continue
        ctx = " ".join(L[max(0, i - 4): i + 5])
        if re.search(r"[+−-]\s?7[.,]5\s?%", line) and not IMT.search(line): continue      # a price change, not a tax
        if (OTHER.search(line) and "IMT" not in line): continue
        if not IMT.search(ctx) and not f.startswith(("content/inbox/", "social/")): continue
        kind = "top bracket" if re.search(r"1[ .,]?150[ .,]?853|above|acima|au-del|top|escal", line, re.I) and not re.search(r"n[ãa]o[- ]resid|non[- ]?r[ée]sid|nonresid", line, re.I) else \
               "non-resident flat" if re.search(r"n[ãa]o[- ]resid|non[- ]?r[ée]sid|nonresid|17\.?º?,? ?n\.?º? ?10|17\(10\)|flat|única|unique", ctx, re.I) else "check"
        g = next((n for n, p in GROUPS if f.startswith(p)), "Other")
        t = re.sub(r"\s+", " ", line.strip()); m = RATE.search(t).start()
        t = (("…" if m > 140 else "") + t[max(0, m - 140): m + 160] + ("…" if len(t) > m + 160 else "")).replace("|", "\\|")
        out.setdefault(g, []).append((f, i + 1, kind, t))
n = sum(len(v) for v in out.values())
print("# Every 7.5% IMT mention, for the legal check\n")
print(f"Generated by `python3 scripts/legal/imt_mentions.py` on the working branch. {n} mentions in {len({x[0] for v in out.values() for x in v})} files. "
      "Regenerate after any change; the e-book HTML in site/ebooks/out/ is built from site/ebooks/build.ts and countries.ts and is not listed separately.\n")
print("**What the repo claims (content/facts/facts.csv, pt-imt-nonresident-flat and pt-imt-nonresident-exceptions):**\n")
print("1. A buyer who is not a Portuguese tax resident pays IMT at a flat 7.5% on an urban property used exclusively for housing, with no exemption or reduction (Código do IMT, art. 17.º, n.º 10, added by Decreto-Lei 97/2026 of 20 May).")
print("2. In force from 25 May 2026 (the general five-day rule; DL 97/2026 has no specific date for this change). To confirm.")
print("3. Exceptions: (a) the buyer has been considered a Portuguese tax resident; (b) the buyer becomes resident within two years of the purchase; (c) the home is let for housing within six months, at a rent within the DL 97/2026 caps, for at least 36 months in the first five years. In (b) and (c) the difference is refunded on request within six months.")
print("4. Separately, 7.5% is also the flat rate for every buyer above 1 150 853 € (art. 17.º, n.º 1, Lei 73-A/2025 brackets). Mentions of that are tagged \"top bracket\".\n")
print("Tags: **non-resident flat** (claim 1–3), **top bracket** (claim 4), **check** (the line alone does not say which; read it in place).\n")
for g, _ in GROUPS + [("Other", "")]:
    if g not in out: continue
    rows = out.pop(g)
    print(f"## {g} ({len(rows)})\n\n| File | Line | Tag | Text |\n| --- | --- | --- | --- |")
    for f, ln, k, t in rows: print(f"| {f} | {ln} | {k} | {t} |")
    print()
